CREATE TABLE decision_models(decision_id text NOT NULL,version text NOT NULL,title text NOT NULL,domain text NOT NULL,risk_level text NOT NULL,payload jsonb NOT NULL,fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(decision_id,version));
CREATE TABLE evidence_items(evidence_id text PRIMARY KEY,decision_id text NOT NULL,source text NOT NULL,observed_at timestamptz NOT NULL,status text NOT NULL,reliability numeric(5,4) NOT NULL CHECK(reliability BETWEEN 0 AND 1),claim text);
CREATE TABLE recommendation_reports(report_fingerprint text PRIMARY KEY,decision_id text NOT NULL,decision_version text NOT NULL,status text NOT NULL,recommended_option_id text,score_gap numeric(8,4) NOT NULL,evidence_boundary text NOT NULL,rankings jsonb NOT NULL,requires_human_approval boolean NOT NULL DEFAULT true,auto_execute boolean NOT NULL DEFAULT false CHECK(auto_execute=false),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scenario_runs(scenario_id text NOT NULL,report_fingerprint text NOT NULL REFERENCES recommendation_reports(report_fingerprint),weights jsonb NOT NULL,rankings jsonb NOT NULL,recommended_option_id text,PRIMARY KEY(scenario_id,report_fingerprint));
CREATE TABLE decision_reviews(audit_fingerprint text PRIMARY KEY,report_fingerprint text NOT NULL REFERENCES recommendation_reports(report_fingerprint),reviewer_id text NOT NULL,reviewer_role text NOT NULL,decision text NOT NULL,rationale text NOT NULL,reviewed_at timestamptz NOT NULL);
CREATE TABLE observed_outcomes(outcome_fingerprint text PRIMARY KEY,report_fingerprint text NOT NULL REFERENCES recommendation_reports(report_fingerprint),selected_option_id text NOT NULL,followed_recommendation boolean NOT NULL,observed_metrics jsonb NOT NULL,evidence_boundary text NOT NULL,recorded_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_outbox(event_id text PRIMARY KEY,payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending',next_attempt_at timestamptz,last_error text);
CREATE TABLE dead_letters(event_id text PRIMARY KEY,payload jsonb NOT NULL,failure_reason text NOT NULL,failed_at timestamptz NOT NULL DEFAULT now());
